"""Write asm/nightshade_hooks_enh.asm: asm/nightshade_hooks.asm with ENHCIM defined (the Enhanced build's hooks:
code images instead of plane plots). Generated: edit nightshade_hooks.asm and run this, then
tools/asm2profile.py nightshade_enh."""
import os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = open(os.path.join(R, 'asm', 'nightshade_hooks.asm')).read()
open(os.path.join(R, 'asm', 'nightshade_hooks_enh.asm'), 'w').write(
    '; GENERATED by tools/nightshade_enh_asm.py from nightshade_hooks.asm: do not edit\n        DEFINE ENHCIM\n' + src
    + '\n        SAVEBIN "ns_page3.bin",0x3300,page3_end-0x3300\n')
